package com.dormrepair.v2.catalog;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.flywaydb.core.Flyway;
import static org.junit.jupiter.api.Assertions.*;
@EnabledIfSystemProperty(named="flowable.v2B",matches="true")
class GrantMigrationTest {
 DriverManagerDataSource ds;JdbcTemplate j;
 @BeforeEach void reset()throws Exception{ds=new DriverManagerDataSource("jdbc:postgresql://127.0.0.1:5432/dorm_repair_v2_test_grants",System.getenv().getOrDefault("V2_DB_USER","sota"),System.getenv().getOrDefault("V2_DB_PASSWORD",""));try(var c=ds.getConnection()){com.dormrepair.v2.platform.migration.V2DatabaseTarget.requireTestReset(c);}j=new JdbcTemplate(ds);j.execute("drop schema if exists v2_business_history cascade");j.execute("drop schema public cascade");j.execute("create schema public");}
 Flyway migrate(String target,String init){var config=Flyway.configure().dataSource(ds).locations("classpath:db/v2/business").defaultSchema("v2_business_history").schemas("v2_business_history").group(true).target(target);if(init!=null)config.initSql(init);var f=config.load();f.migrate();return f;}
 String mapping(){return "create temporary table c6_confirmed_grants(role_id bigint,permission_code varchar(80),primary key(role_id,permission_code));insert into c6_confirmed_grants select r.id,p.code from public.sys_role r cross join public.sys_permission p where r.code='ADMIN' and p.code in ('category:write','space:write','facility:write');";}
 void users(){j.update("insert into public.sys_user(username,password_hash,real_name,role) values ('synthetic_admin','unchanged','Synthetic admin','ADMIN'),('synthetic_student','unchanged','Synthetic student','STUDENT')");}
 @Test void freshEmptyAndRepeat(){migrate("latest",null);assertEquals(0,j.queryForObject("select count(*) from public.sys_user",Integer.class));assertEquals(16,j.queryForObject("select count(*) from public.sys_role_permission rp join public.sys_role r on r.id=rp.role_id where r.code='ADMIN'",Integer.class));assertEquals(0,j.queryForObject("select count(*) from public.sys_role_permission rp join public.sys_role r on r.id=rp.role_id join public.sys_permission p on p.id=rp.permission_id where r.code in ('STUDENT','REPAIRER') and p.code like '%:write' and p.module='V2_FOUNDATION'",Integer.class));assertEquals(0,migrate("latest",null).migrate().migrationsExecuted);}
 @Test void v5EmptySeedTemplatesAreNormalized(){migrate("5",null);j.update("insert into public.sys_role_permission select r.id,p.id from public.sys_role r cross join public.sys_permission p where r.code='STUDENT' and p.code='facility:write'");migrate("latest",null);assertEquals(0,j.queryForObject("select count(*) from public.sys_role_permission rp join public.sys_role r on r.id=rp.role_id join public.sys_permission p on p.id=rp.permission_id where r.code='STUDENT' and p.code='facility:write'",Integer.class));}
 @Test void emptyCustomRolesRefuseWithoutMutation(){migrate("5",null);j.update("insert into public.sys_role(code,name) values ('UNKNOWN','Unknown')");assertThrows(Exception.class,()->migrate("latest",null));assertEquals(4,j.queryForObject("select count(*) from public.sys_role",Integer.class));assertEquals(0,j.queryForObject("select count(*) from v2_business_history.flyway_schema_history where version='6'",Integer.class));}
 @Test void nonemptyWithoutEvidenceRefusesAtomically(){migrate("5",null);users();var before=j.queryForList("select * from public.sys_role_permission order by role_id,permission_id");assertThrows(Exception.class,()->migrate("latest",null));assertEquals(before,j.queryForList("select * from public.sys_role_permission order by role_id,permission_id"));assertEquals(0,j.queryForObject("select sum(auth_version) from public.sys_user",Integer.class));}
 @Test void confirmedMappingRepairsSharedRoleAndPreservesLegitimateGrant(){migrate("3",null);users();j.update("insert into public.sys_user_role select u.id,r.id from public.sys_user u cross join public.sys_role r where u.username='synthetic_admin' and r.code='STUDENT'");migrate("5",null);assertTrue(j.queryForObject("select count(*)>0 from public.sys_role_permission rp join public.sys_role r on r.id=rp.role_id join public.sys_permission p on p.id=rp.permission_id where r.code='STUDENT' and p.code='facility:write'",Boolean.class));j.update("insert into public.sys_role(code,name) values ('LEGIT','Approved limited role')");j.update("insert into public.sys_role_permission select r.id,p.id from public.sys_role r cross join public.sys_permission p where r.code='LEGIT' and p.code='category:write'");String init=mapping()+"insert into c6_confirmed_grants select id,'category:write' from public.sys_role where code='LEGIT';";migrate("latest",init);assertEquals(1,new com.dormrepair.v2.identity.RbacRepository(j).managers());assertEquals(0,j.queryForObject("select count(*) from public.sys_role_permission rp join public.sys_role r on r.id=rp.role_id join public.sys_permission p on p.id=rp.permission_id where r.code='STUDENT' and p.code in ('category:write','space:write','facility:write')",Integer.class));assertEquals(1,j.queryForObject("select count(*) from public.sys_role_permission rp join public.sys_role r on r.id=rp.role_id join public.sys_permission p on p.id=rp.permission_id where r.code='LEGIT' and p.code='category:write'",Integer.class));assertEquals(4,j.queryForObject("select sum(auth_version) from public.sys_user",Integer.class));}
 @Test void losingLastCustodianRollsBack(){migrate("5",null);users();String init="create temporary table c6_confirmed_grants(role_id bigint,permission_code varchar(80));";var before=j.queryForList("select * from public.sys_role_permission order by role_id,permission_id");assertThrows(Exception.class,()->migrate("latest",init));assertEquals(before,j.queryForList("select * from public.sys_role_permission order by role_id,permission_id"));}
}

